r.get('/crm/whatsapp-workspace/conversations/:id',async(req,res)=>{
    const conversation=await selectConversationWithReplyLock(undefined,req.params.id);
    if(!conversation||!canUseConversation(req.broker,conversation))return res.status(404).json({error:'Conversation not found or outside your inbox scope'});
    const related=await one(`SELECT team.name AS team_name,agent.name AS owner_agent_name,l.lead_reference,l.title AS lead_title
      FROM wa_conversations c JOIN teams team ON team.id=c.owner_team_id LEFT JOIN brokers agent ON agent.id=c.owner_agent_id
      LEFT JOIN leads l ON l.id=c.lead_id WHERE c.id=$1`,[conversation.id]);
    Object.assign(conversation,related||{});
  const messages=await many('SELECT id,direction,message_type,body,occurred_at,simulated,provider_message_id,provider_status,provider_status_at FROM wa_conversation_messages WHERE conversation_id=$1 ORDER BY occurred_at ASC LIMIT 500',[conversation.id]);
  const agents=['manager','director'].includes(req.broker.jobRole)?await many(`SELECT DISTINCT b.id,b.name FROM brokers b WHERE b.status='active' AND b.job_role='sales_agent' AND (b.team_id=$1 OR EXISTS(SELECT 1 FROM team_memberships tm WHERE tm.team_id=$1 AND tm.broker_id=b.id AND tm.ends_at IS NULL) OR EXISTS(SELECT 1 FROM user_role_assignments ur WHERE ur.team_id=$1 AND ur.broker_id=b.id AND ur.status='active' AND ur.ends_at IS NULL)) ORDER BY b.name`,[conversation.ownerTeamId]):[];
  await execute('UPDATE wa_inbox_notifications SET read_at=NOW() WHERE conversation_id=$1 AND broker_id=$2 AND read_at IS NULL',[conversation.id,req.broker.id]);
    const now=Date.now(),simulation=simulatedProviderConfig(),lockState=replyLockState(conversation,req.broker),lockDisplay=lockState.active?`${lockState.ownerName||'another user'} until ${new Date(lockState.expiresAt).toISOString()}`:'available';res.json({conversation:{...conversation,replyLockOwnerName:lockDisplay,replyLock:lockState,replyWindowOpen:Boolean(conversation.lastCustomerMessageAt&&now-Date.parse(conversation.lastCustomerMessageAt)<=24*60*60*1000),ctwaFreeWindowOpen:Boolean(['ctwa','website_ctwa'].includes(conversation.sourceType)&&conversation.ctwaEntryAt&&now-Date.parse(conversation.ctwaEntryAt)<=72*60*60*1000)},messages,agents,sendingEnabled:Boolean(simulation.enabled&&conversation.simulated&&lockState.canSend),simulationEnabled:simulation.enabled});
});

r.post('/crm/whatsapp-workspace/conversations/:id/reply-lock',async(req,res)=>{
  const action=clean(req.body?.action,20);if(!['acquire','release'].includes(action))return res.status(400).json({error:'Reply lock action must be acquire or release'});
  const result=await transaction(async client=>{
    const conversation=await selectConversationWithReplyLock(client,req.params.id,{forUpdate:true});
    if(!conversation)return{code:404,error:'Conversation not found'};
    if(!canUseTeam(req.broker,conversation.ownerTeamId))return{code:403,error:'Conversation is outside your scope'};
    if(req.broker.jobRole==='sales_agent'&&String(conversation.ownerAgentId)!==String(req.broker.id))return{code:403,error:'Only the conversation owner may hold its reply lock'};
    const before=replyLockState(conversation,req.broker);
    if(action==='acquire'&&before.active&&!before.heldByCurrentUser)return{code:409,error:`Reply lock held by ${before.ownerName||'another user'} until ${new Date(before.expiresAt).toISOString()}`,response:{error:`Reply lock held by ${before.ownerName||'another user'} until ${new Date(before.expiresAt).toISOString()}`,code:'WHATSAPP_REPLY_LOCK_HELD',replyLock:before}};
    if(action==='release'&&conversation.replyLockOwnerId&&!before.heldByCurrentUser&&!['manager','director'].includes(req.broker.jobRole))return{code:403,error:'Only the lock holder or a Manager/Director may release it'};
    if(action==='release'&&!conversation.replyLockOwnerId)return{conversation,replyLock:before,noOp:true};
    const updated=await writeReplyLock(client,conversation.id,action==='acquire'?req.broker.id:null),after=replyLockState(updated,req.broker);
    const auditAction=action==='release'?'reply_lock_released':before.expired?'reply_lock_expired_replaced':'reply_lock_acquired';
    const details=action==='release'?{priorHolderId:before.ownerId,priorAcquiredAt:before.acquiredAt,priorExpiresAt:before.expiresAt,releaseMode:before.heldByCurrentUser?'holder':'manager_override'}:{priorHolderId:before.ownerId,priorAcquiredAt:before.acquiredAt,priorExpiresAt:before.expiresAt,newHolderId:after.ownerId,newAcquiredAt:after.acquiredAt,newExpiresAt:after.expiresAt,reacquired:before.active&&before.heldByCurrentUser};
    await audit('WhatsAppConversation',conversation.id,auditAction,req.broker.id,details,client);
    return{conversation:updated,replyLock:after};
  });
  if(result.error)return res.status(result.code).json(result.response||{error:result.error});res.json(result);
});

